 if(tab==='You')return <><BirthProfile aiConsent={aiProvider&&!aiAllowed?null:aiAllowed?aiProvider:''} onUpgrade={()=>setPaywall(true)}/><Pressable accessibilityRole="button" onPress={()=>setPaywall(true)} style={[styles.row,{paddingVertical:16,borderBottomWidth:1,borderColor:'#614C34',flexWrap:'wrap'}]}><View style={{flexShrink:1}}><Txt>{state.plus?(purchaseMode==='mock'?'Plus · test':'Plus'):'Free plan'}</Txt><Txt style={styles.caption}>{state.plus?'10':'1'} reading{state.plus?'s':''} a day · {remaining} left today</Txt></View><Txt style={{color:colors.ice}}>See plans →</Txt></Pressable><BackupPanel/><Txt display style={[styles.title,{marginTop:32}]}>What the Ball remembers</Txt><Txt style={styles.caption}>Used so it doesn’t ask twice. Edit or forget anything.</Txt>{!Object.keys(state.facts).length?<View style={styles.panel}><Txt>Still a beautiful mystery.</Txt><Txt style={styles.caption}>As you answer, useful details will appear here.</Txt></View>:Object.entries(state.facts).map(([key,value])=><View key={key} style={{paddingVertical:16,borderBottomWidth:1,borderColor:'#614C34'}}><Txt style={styles.caption}>{factLabels[key]||key.replaceAll('_',' ')}</Txt>{edit===key?<><TextInput accessibilityLabel={`Edit ${key}`} value={editValue} onChangeText={setEditValue} style={styles.input} maxLength={300}/><Action label="Save fact" onPress={()=>{const next=editValue.trim();if(!next){setEdit(null);return;}try{validateFact(key,next)}catch(error){setNotice(error instanceof Error?error.message:'Please check this value.');return;}update(s=>({...s,facts:{...s.facts,[key]:next}}));setNotice('');setEdit(null)}}/></>:<><Txt>{value}</Txt><View style={{flexDirection:'row',gap:12,marginTop:12}}><Pressable testID={`edit-${key}`} accessibilityRole="button" accessibilityLabel={`Edit ${key}`} onPress={()=>{setEdit(key);setEditValue(value)}} style={{width:state.largeText?'48%':96,padding:12,minHeight:52,alignItems:'center',justifyContent:'center',borderWidth:1,borderColor:'#614C34',borderRadius:12}}><Txt style={{color:colors.ice}}>Edit</Txt></Pressable><Pressable accessibilityRole="button" accessibilityLabel={`Forget ${key}`} onPress={()=>{setUndoFact({key,value});update(s=>{const facts={...s.facts};delete facts[key];return {...s,facts}});setNotice(`Forgot ${factLabels[key]||key.replaceAll('_',' ')}.`)}} style={{width:state.largeText?'48%':96,padding:12,minHeight:52,alignItems:'center',justifyContent:'center',borderWidth:1,borderColor:'#614C34',borderRadius:12}}><Txt style={{color:colors.muted}}>Forget</Txt></Pressable></View></>}</View>)}<Action testID="open-inner-library" label={state.plus?'Inner Library · ball and card styles':'Inner Library · Plus'} quiet onPress={()=>switchTab('Library')}/><View style={[styles.row,{marginTop:28}]}><Txt>Ambient sound</Txt><Switch testID="ambient-sound" accessibilityLabel="Ambient sound" value={!!state.ambientSound} onValueChange={value=>update(s=>({...s,ambientSound:value}))}/></View><View style={[styles.row,{marginTop:28}]}><Txt>Reduce motion</Txt><Switch accessibilityLabel="Reduce motion" value={state.reduceMotion} onValueChange={value=>update(s=>({...s,reduceMotion:value}))} trackColor={{true:colors.lavender,false:'#614C34'}}/></View><View style={[styles.row,{marginTop:20}]}><Txt>Large text (200%)</Txt><Switch accessibilityLabel="Large text" value={state.largeText} onValueChange={value=>update(s=>({...s,largeText:value}))}/></View><Action label="View plans and credits" quiet onPress={()=>setPaywall(true)}/><Action label="Privacy and entertainment" quiet onPress={()=>setPrivacyOpen(!privacyOpen)}/>{privacyOpen?<View style={styles.panel}><Txt style={styles.caption}>Forecasts are speculative entertainment, not facts or medical, legal or financial advice. Questions and relevant answers go to the prediction engine. When configured, Supabase stores your history and remembered answers under your account ID. Public world-event topics go to Google News. Voice uses your device’s speech service. We do not add advertising or tracking. Forgetting a fact updates remembered answers. Changing or forgetting your birthday also removes it from saved reading facts. Changing or forgetting your birthday, or forgetting birth time and place, deletes saved astrology lines; the readings themselves remain. Other forgotten facts stay in past readings. Forget everything clears readings and remembered answers on this device. Deletions stay saved on this device offline and replace the backup on the next successful upload. Use one device at a time: the last upload replaces the archive. Restore explicitly replaces this device’s readings and remembered answers. Your plan and credits stay. It does not delete your Apple account. Public privacy policy and account deletion must be configured before launch.</Txt></View>:null}<Action label="Forget everything" quiet onPress={()=>{if(Platform.OS==='web'){if(window.confirm('Delete all saved readings and remembered facts? Your plan and credits stay.')){void forgetEverything();}}else Alert.alert('Forget everything?','Deletes saved readings and remembered facts. Your plan and credits stay.',[{text:'Keep',style:'cancel'},{text:'Delete',style:'destructive',onPress:()=>{void forgetEverything()}}])}}/><Txt style={[styles.caption,{marginTop:16}]}>For entertainment only. Not medical, legal or financial advice.</Txt></>;
 if(flow.stage==='approach')return <View style={{flexGrow:1,justifyContent:'center',alignItems:'center',paddingBottom:100}}><Txt display style={{fontFamily:fonts.italic,fontSize:32}}>Come closer…</Txt><Txt style={[styles.caption,{marginTop:8}]}>The Ball is ready to listen.</Txt></View>;
